{
  "question_num": 5,
  "total_marks": 10,
  "title": "D.C. circuits",
  "main_stem": "A student sets up a circuit with a battery, an ammeter, a heater and a light-dependent resistor (LDR) all in series.\n\nThe battery has negligible internal resistance.\n\nA voltmeter is connected across (in parallel with) the heater.",
  "parts": [
    {
      "label": "(a)",
      "part_stem": null,
      "text": "On Fig. 5.1, complete the circuit diagram of this arrangement.",
      "marks": 3,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(i)",
      "part_stem": "The heater is a wire made of metal of resistivity $1.1 \\times 10^{-6} \\Omega \\text{m}$. The wire has length $2.0 \\text{m}$ and cross-sectional area $3.8 \\times 10^{-7} \\text{m}^2$.\n\nThe reading on the voltmeter is $4.8 \\text{V}$.\n\nCalculate:",
      "text": "the resistance of the heater",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(ii)",
      "part_stem": null,
      "text": "the reading on the ammeter.",
      "marks": 1,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(c)(i)",
      "part_stem": "The heater is replaced by a new wire. The new wire is made of the same metal as the wire in (b) and has the same length but a larger diameter.\n\nThe resistance of the LDR remains constant.",
      "text": "State and explain whether the new wire has a resistance that is greater than, less than or the same as that of the wire in (b).",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(c)(ii)",
      "part_stem": null,
      "text": "State and explain whether the new reading on the voltmeter is greater than, less than or equal to $4.8 \\text{V}$.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    }
  ],
  "markscheme": [
    {
      "label": "(a)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "M1",
          "text": "correct symbol for heater or for the LDR"
        },
        {
          "tag": "A1",
          "text": "battery, ammeter, heater and LDR in series (ignore voltmeter) and no extra symbols"
        },
        {
          "tag": "B1",
          "text": "correct symbol for voltmeter and in parallel with the heater"
        }
      ]
    },
    {
      "label": "(b)(i)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "C1",
          "text": "$R = \\rho l / A$"
        },
        {
          "tag": "A1",
          "text": "$R (= \\rho l / A) = (1.1 \\times 10^{-6} \\times 2.0) / 3.8 \\times 10^{-7} = 5.8 \\, \\Omega$"
        }
      ]
    },
    {
      "label": "(b)(ii)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "A1",
          "text": "$I (= V / R) = 4.8 / 5.8 = 0.83 \\, \\text{A}$"
        }
      ]
    },
    {
      "label": "(c)(i)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "M1",
          "text": "larger (cross-sectional) area for new wire (so) lower resistance for new wire"
        },
        {
          "tag": "A1",
          "text": "less than (resistance of) first wire"
        }
      ]
    },
    {
      "label": "(c)(ii)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "M1",
          "text": "total resistance decreases so current (in circuit) increases (so p.d. across LDR increases) / new wire has a smaller share/proportion/fraction of the (total) voltage / e.m.f."
        },
        {
          "tag": "A1",
          "text": "less (than $4.8 \\text{V}$)"
        }
      ]
    }
  ]
}
